@page "/settings"
@rendermode InteractiveServer
@using sv_3ff1f3b3e2484bfbb82e7950fccf86a8.Services
@inject ISettingsService SettingsService
@inject IJSRuntime JS

<PageTitle>Settings</PageTitle>

@if (_loading)
{
    <div class="d-flex justify-content-center align-items-center" style="min-height: 400px;">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    @if (_successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show settings-toast" role="alert">
            @_successMessage
        </div>
    }

    <h2 class="mb-4">Settings</h2>

    <div class="row">
        <!-- Sidebar -->
        <div class="col-3">
            <div class="nav flex-column nav-pills settings-nav" role="tablist">
                <button class="nav-link @ActiveClass("Profile")" @onclick='() => _activeSection = "Profile"'>
                    <span>👤</span> Profile
                </button>
                <button class="nav-link @ActiveClass("Notifications")" @onclick='() => _activeSection = "Notifications"'>
                    <span>🔔</span> Notifications
                </button>
                <button class="nav-link @ActiveClass("Security")" @onclick='() => _activeSection = "Security"'>
                    <span>🔒</span> Security
                </button>
                <button class="nav-link @ActiveClass("Appearance")" @onclick='() => _activeSection = "Appearance"'>
                    <span>🎨</span> Appearance
                </button>
            </div>
        </div>

        <!-- Content -->
        <div class="col-9">
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        </div>
    </div>
}

@code {
    private bool _loading = true;
    private string _activeSection = "Profile";
    private string? _successMessage;
    private bool _saving;

    // Profile
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // Notifications
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = new() { "general", "marketing", "random", "engineering", "design" };
    private HashSet<string> _mutedChannels = new();

    // Security
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _showChangePassword;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;

    // Appearance
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        _security = securityTask.Result;
        _twoFactorEnabled = _security.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;

        _loading = false;
    }

    private string ActiveClass(string section) => _activeSection == section ? "active" : "";

    private async Task ShowSuccess(string message)
    {
        _successMessage = message;
        StateHasChanged();
        await Task.Delay(3000);
        _successMessage = null;
        StateHasChanged();
    }

    // ── Profile ──

    private RenderFragment RenderProfile() => __builder =>
    {
        <h4 class="mb-3">Profile Settings</h4>

        <div class="card mb-4">
            <div class="card-body">
                <div class="row mb-3">
                    <div class="col-md-8">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Display Name</label>
                            <input type="text" class="form-control" @bind="_displayName" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Email</label>
                            <input type="email" class="form-control" @bind="_email" />
                        </div>
                    </div>
                    <div class="col-md-4 text-center">
                        <div class="mb-2">
                            <img src="@_avatarUrl" alt="Avatar" class="avatar-preview rounded-circle" />
                        </div>
                        <small class="text-muted text-break">@_avatarUrl</small>
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="3" @bind="_bio"></textarea>
                </div>
                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Save Changes
                    </button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfile" disabled="@_saving">
                        Discard Changes
                    </button>
                </div>
            </div>
        </div>
    };

    private async Task SaveProfile()
    {
        _saving = true;
        StateHasChanged();
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _ = ShowSuccess("Profile saved successfully!");
    }

    private void DiscardProfile()
    {
        if (_savedProfile is null) return;
        _displayName = _savedProfile.DisplayName;
        _email = _savedProfile.Email;
        _avatarUrl = _savedProfile.AvatarUrl;
        _bio = _savedProfile.Bio;
    }

    // ── Notifications ──

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h4 class="mb-3">Notification Preferences</h4>

        <div class="card mb-4">
            <div class="card-body">
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>
                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>

                <hr />
                <h6 class="mb-3">Muted Channels</h6>
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{ch}")">@($"#{ch}")</label>
                    </div>
                }

                <hr />
                <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Preferences
                </button>
            </div>
        </div>
    };

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        StateHasChanged();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _ = ShowSuccess("Notification preferences saved!");
    }

    // ── Security ──

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h4 class="mb-3">Security Settings</h4>

        <!-- Change Password -->
        <div class="card mb-4">
            <div class="card-body">
                <h6>
                    <button class="btn btn-link text-decoration-none p-0" @onclick="() => _showChangePassword = !_showChangePassword">
                        @(_showChangePassword ? "▾" : "▸") Change Password
                    </button>
                </h6>
                @if (_security?.LastPasswordChange is not null)
                {
                    <small class="text-muted">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
                }

                @if (_showChangePassword)
                {
                    <div class="mt-3">
                        @if (_passwordError is not null)
                        {
                            <div class="alert alert-danger py-2">@_passwordError</div>
                        }
                        @if (_passwordSuccess is not null)
                        {
                            <div class="alert alert-success py-2">@_passwordSuccess</div>
                        }
                        <div class="mb-3">
                            <label class="form-label">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-warning" @onclick="ChangePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>
        </div>

        <!-- Two-Factor Authentication -->
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-danger">Disabled</span>
                    }
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="mb-3">Active Sessions</h6>
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (_security?.Sessions is not null)
                            {
                                @for (int i = 0; i < _security.Sessions.Count; i++)
                                {
                                    var session = _security.Sessions[i];
                                    var isCurrent = i == 0;
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrent) { <span class="badge bg-info ms-1">Current</span> }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (!isCurrent)
                                            {
                                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RevokeSession(session.Id)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    };

    private string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private async Task ChangePassword()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "Please fill in all password fields.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        StateHasChanged();
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _saving = false;
        _passwordSuccess = "Password updated successfully!";
    }

    private async Task RevokeSession(string sessionId)
    {
        var confirmed = await JS.InvokeAsync<bool>("confirm", "Are you sure you want to revoke this session?");
        if (!confirmed) return;

        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
        StateHasChanged();
    }

    // ── Appearance ──

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h4 class="mb-3">Appearance Settings</h4>

        <div class="card mb-4">
            <div class="card-body">
                <!-- Theme -->
                <h6 class="mb-2">Theme</h6>
                <div class="mb-3">
                    @foreach (var t in new[] { "Light", "Dark", "System" })
                    {
                        var theme = t;
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <h6 class="mb-2">Font Size</h6>
                <div class="mb-3">
                    @foreach (var fs in new[] { "Small", "Medium", "Large" })
                    {
                        var size = fs;
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <h6 class="mb-2">Language</h6>
                <div class="mb-3">
                    <select class="form-select" style="max-width: 250px;" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="form-check form-switch mb-4">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>

                <!-- Live Preview -->
                <h6 class="mb-2">Preview</h6>
                <div class="card mb-3" style="@GetPreviewStyle()">
                    <div class="card-body" style="@GetPreviewPadding()">
                        <h6 style="@GetPreviewTextColor()">Preview Card</h6>
                        <p style="@GetPreviewFontSize() @GetPreviewTextColor()" class="mb-0">
                            The quick brown fox jumps over the lazy dog. This is how your content will look with the selected settings.
                        </p>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>
        </div>
    };

    private string GetPreviewStyle()
    {
        var bg = _theme == "Dark" ? "background-color: #1e1e1e; border-color: #444;" : "background-color: #fff;";
        return bg;
    }

    private string GetPreviewPadding() => _compactMode ? "padding: 0.5rem;" : "padding: 1.25rem;";

    private string GetPreviewTextColor() => _theme == "Dark" ? "color: #e0e0e0;" : "color: #212529;";

    private string GetPreviewFontSize()
    {
        var px = _fontSize switch
        {
            "Small" => "13px",
            "Large" => "18px",
            _ => "15px"
        };
        return $"font-size: {px};";
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        StateHasChanged();
        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _ = ShowSuccess("Appearance settings saved!");
    }
}

.settings-nav .nav-link {
    text-align: left;
    border-radius: 0.5rem;
    margin-bottom: 0.25rem;
    color: #495057;
    transition: background-color 0.2s, color 0.2s;
}

.settings-nav .nav-link:hover {
    background-color: #e9ecef;
}

.settings-nav .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-nav .nav-link span {
    margin-right: 0.5rem;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.settings-toast {
    position: fixed;
    top: 1rem;
    right: 1rem;
    z-index: 1055;
    min-width: 280px;
    animation: slideIn 0.3s ease-out;
}

@@keyframes slideIn {
    from {
        transform: translateX(100%);
        opacity: 0;
    }
    to {
        transform: translateX(0);
        opacity: 1;
    }
}

