+    // ── Notifications ──
+
+    private RenderFragment RenderNotifications() => __builder =>
+    {
+        <h4 class="mb-3">Notification Preferences</h4>
+
+        <div class="card mb-4">
+            <div class="card-body">
+                <div class="form-check form-switch mb-3">
+                    <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
+                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
+                </div>
+                <div class="form-check form-switch mb-3">
+                    <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
+                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
+                </div>
+                <div class="form-check form-switch mb-3">
+                    <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
+                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
+                </div>
+
+                <hr />
+                <h6 class="mb-3">Muted Channels</h6>
+                @foreach (var channel in _allChannels)
+                {
+                    var ch = channel;
+                    <div class="form-check mb-2">
+                        <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
+                               checked="@_mutedChannels.Contains(ch)"
+                               @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
+                        <label class="form-check-label" for="@($"ch-{ch}")">@($"#{ch}")</label>
+                    </div>
+                }
+
+                <hr />
+                <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
+                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                    Save Preferences
+                </button>
+            </div>
+        </div>
+    };
+
+    private void ToggleMutedChannel(string channel, bool muted)
+    {
+        if (muted) _mutedChannels.Add(channel);
+        else _mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveNotifications()
+    {
+        _saving = true;
+        StateHasChanged();
+        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        _saving = false;
+        _ = ShowSuccess("Notification preferences saved!");
+    }
+
+    // ── Security ──
+
+    private RenderFragment RenderSecurity() => __builder =>
+    {
+        <h4 class="mb-3">Security Settings</h4>
+
+        <!-- Change Password -->
+        <div class="card mb-4">
+            <div class="card-body">
+                <h6>
+                    <button class="btn btn-link text-decoration-none p-0" @onclick="() => _showChangePassword = !_showChangePassword">
+                        @(_showChangePassword ? "▾" : "▸") Change Password
+                    </button>
+                </h6>
+                @if (_security?.LastPasswordChange is not null)
+                {
+                    <small class="text-muted">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
+                }
+
+                @if (_showChangePassword)
+                {
+                    <div class="mt-3">
+                        @if (_passwordError is not null)
+                        {
+                            <div class="alert alert-danger py-2">@_passwordError</div>
+                        }
+                        @if (_passwordSuccess is not null)
+                        {
+                            <div class="alert alert-success py-2">@_passwordSuccess</div>
+                        }
+                        <div class="mb-3">
+                            <label class="form-label">Current Password</label>
+                            <input type="password" class="form-control" @bind="_currentPassword" />
+                        </div>
+                        <div class="mb-3">
+                            <label class="form-label">New Password</label>
+                            <input type="password" class="form-control" @bind="_newPassword" />
+                        </div>
+                        <div class="mb-3">
+                            <label class="form-label">Confirm New Password</label>
+                            <input type="password" class="form-control" @bind="_confirmPassword" />
+                        </div>
+                        <button class="btn btn-warning" @onclick="ChangePassword" disabled="@_saving">
+                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                            Update Password
+                        </button>
+                    </div>
+                }
+            </div>
+        </div>
+
+        <!-- Two-Factor Authentication -->
+        <div class="card mb-4">
+            <div class="card-body d-flex justify-content-between align-items-center">
+                <div>
+                    <h6 class="mb-1">Two-Factor Authentication</h6>
+                    @if (_twoFactorEnabled)
+                    {
+                        <span class="badge bg-success">Enabled</span>
+                    }
+                    else
+                    {
+                        <span class="badge bg-danger">Disabled</span>
+                    }
+                </div>
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" id="twoFactor" @bind="_twoFactorEnabled" />
+                </div>
+            </div>
+        </div>
+
+        <!-- Active Sessions -->
+        <div class="card mb-4">
+            <div class="card-body">
+                <h6 class="mb-3">Active Sessions</h6>
+                <div class="table-responsive">
+                    <table class="table table-hover mb-0">
+                        <thead>
+                            <tr>
+                                <th>Device</th>
+                                <th>Location</th>
+                                <th>Last Active</th>
+                                <th></th>
+                            </tr>
+                        </thead>
+                        <tbody>
+                            @if (_security?.Sessions is not null)
+                            {
+                                @for (int i = 0; i < _security.Sessions.Count; i++)
+                                {
+                                    var session = _security.Sessions[i];
+                                    var isCurrent = i == 0;
+                                    <tr>
+                                        <td>
+                                            @session.Device
+                                            @if (isCurrent) { <span class="badge bg-info ms-1">Current</span> }
+                                        </td>
+                                        <td>@session.Location</td>
+                                        <td>@FormatLastActive(session.LastActive)</td>
+                                        <td>
+                                            @if (!isCurrent)
+                                            {
+                                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RevokeSession(session.Id)">
+                                                    Revoke
+                                                </button>
+                                            }
+                                        </td>
+                                    </tr>
+                                }
+                            }
+                        </tbody>
+                    </table>
+                </div>
+            </div>
+        </div>
+    };
+
+    private string FormatLastActive(DateTime dt)
+    {
+        var diff = DateTime.UtcNow - dt;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
+        return $"{(int)diff.TotalDays} days ago";
+    }
+
+    private async Task ChangePassword()
+    {
+        _passwordError = null;
+        _passwordSuccess = null;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
+        {
+            _passwordError = "Please fill in all password fields.";
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            _passwordError = "New password and confirmation do not match.";
+            return;
+        }
+
+        _saving = true;
+        StateHasChanged();
+        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+        _security = await SettingsService.GetSecuritySettingsAsync();
+        _currentPassword = "";
+        _newPassword = "";
+        _confirmPassword = "";
+        _saving = false;
+        _passwordSuccess = "Password updated successfully!";
+    }
+
+    private async Task RevokeSession(string sessionId)
+    {
+        var confirmed = await JS.InvokeAsync<bool>("confirm", "Are you sure you want to revoke this session?");
+        if (!confirmed) return;
+
+        await SettingsService.RevokeSessionAsync(sessionId);
+        _security = await SettingsService.GetSecuritySettingsAsync();
+        StateHasChanged();
+    }
+
+    // ── Appearance ──
+
+    private RenderFragment RenderAppearance() => __builder =>
+    {
+        <h4 class="mb-3">Appearance Settings</h4>
+
+        <div class="card mb-4">
+            <div class="card-body">
+                <!-- Theme -->
+                <h6 class="mb-2">Theme</h6>
+                <div class="mb-3">
+                    @foreach (var t in new[] { "Light", "Dark", "System" })
+                    {
+                        var theme = t;
+                        <div class="form-check form-check-inline">
+                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
+                                   value="@theme" checked="@(_theme == theme)"
+                                   @onchange="() => _theme = theme" />
+                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
+                        </div>
+                    }
+                </div>
+
+                <!-- Font Size -->
+                <h6 class="mb-2">Font Size</h6>
+                <div class="mb-3">
+                    @foreach (var fs in new[] { "Small", "Medium", "Large" })
+                    {
+                        var size = fs;
+                        <div class="form-check form-check-inline">
+                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
+                                   value="@size" checked="@(_fontSize == size)"
+                                   @onchange="() => _fontSize = size" />
+                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
+                        </div>
+                    }
+                </div>
+
+                <!-- Language -->
+                <h6 class="mb-2">Language</h6>
+                <div class="mb-3">
+                    <select class="form-select" style="max-width: 250px;" @bind="_language">
+                        <option value="English">English</option>
+                        <option value="Spanish">Spanish</option>
+                        <option value="French">French</option>
+                        <option value="German">German</option>
+                        <option value="Japanese">Japanese</option>
+                    </select>
+                </div>
+
+                <!-- Compact Mode -->
+                <div class="form-check form-switch mb-4">
+                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
+                    <label class="form-check-label" for="compactMode">Compact Mode</label>
+                </div>
+
+                <!-- Live Preview -->
+                <h6 class="mb-2">Preview</h6>
+                <div class="card mb-3" style="@GetPreviewStyle()">
+                    <div class="card-body" style="@GetPreviewPadding()">
+                        <h6 style="@GetPreviewTextColor()">Preview Card</h6>
+                        <p style="@GetPreviewFontSize() @GetPreviewTextColor()" class="mb-0">
+                            The quick brown fox jumps over the lazy dog. This is how your content will look with the selected settings.
+                        </p>
+                    </div>
+                </div>
+
+                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
+                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                    Save
+                </button>
+            </div>
+        </div>
+    };
+
+    private string GetPreviewStyle()
+    {
+        var bg = _theme == "Dark" ? "background-color: #1e1e1e; border-color: #444;" : "background-color: #fff;";
+        return bg;
+    }
+
+    private string GetPreviewPadding() => _compactMode ? "padding: 0.5rem;" : "padding: 1.25rem;";
+
+    private string GetPreviewTextColor() => _theme == "Dark" ? "color: #e0e0e0;" : "color: #212529;";
+
+    private string GetPreviewFontSize()
+    {
+        var px = _fontSize switch
+        {
+            "Small" => "13px",
+            "Large" => "18px",
+            _ => "15px"
+        };
+        return $"font-size: {px};";
+    }
+
+    private async Task SaveAppearance()
+    {
+        _saving = true;
+        StateHasChanged();
+        await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
+        _saving = false;
+        _ = ShowSuccess("Appearance settings saved!");
+    }
+}
+

